static async _initShopElements () {
	// Shops are generated by the homebrew manager's shop book, so the nav can't list them
	// statically. Mirrors _initAdventureBookElements: fetch, then add one entry
	// per shop. An absent or invalid file leaves the nav exactly as it was.
	let shops;
	try {
		const json = await DataUtil.loadJSON(`${Renderer.get().baseUrl}data/shops.json`);
		shops = json?.shop || [];
	} catch (e) { return; }
	if (!shops.length) return;

	shops
		.sort((a, b) => SortUtil.ascSortLower(a.name, b.name))
		.forEach(shop => {
			NavBar._addElement_li({
				keyPath: [NavBar._CAT_REFERENCES],
				page: `shops.html?shop=${encodeURIComponent(shop.id)}`,
				aText: shop.name,
			});
		});
}

